import type { LessonStep, WorkshopTechnique } from '../content/workshop/types';
import type { PipelineId } from '../content/pipeline';

type Pair = [string, string];
export function fiveLevelTechniques(locale: 'vi' | 'en'): Partial<Record<PipelineId, WorkshopTechnique[]>> {
  const t = (p: Pair) => p[locale === 'en' ? 1 : 0];
  const step = (title: Pair, tool: string, instruction: Pair, save: string, prompt?: string): LessonStep => ({ title: t(title), tool, instruction: t(instruction), save, ...(prompt ? { prompt } : {}) });
  const lab = (id: string, title: Pair, goal: Pair, input: Pair, steps: LessonStep[], check: Pair, fix: Pair): WorkshopTechnique => ({ id, title: t(title), goal: t(goal), input: t(input), steps, check: t(check), fix: t(fix) });
  return {
    story: [
      lab('prompt-remix', ['Từ prompt mẫu đến ý tưởng riêng', 'From a template prompt to your own idea'],
        ["Viết rõ năm điều: chủ thể → hành động → bối cảnh → góc máy và chuyển động camera → chi tiết cần giữ nguyên. Mỗi lần thử chỉ đổi một điều.", 'Understand a short clip as subject → action → setting → camera → constraints. Adapt deliberately rather than copying the entire prompt.'],
        ['Một ý tưởng tự viết: người giao thư phát hiện hộp thư phát sáng. Khung ngang 16:9, một cú máy.', 'An original idea: a courier discovers a glowing mailbox. Landscape 16:9, one shot.'], [
          step(['Tách phần cố định và phần biến đổi', 'Separate constants from variables'], 'Notes', ["Viết 5 dòng: ai, làm gì, ở đâu, máy quay, điều không được đổi. Bản A là người giao thư trong con hẻm vào buổi sáng; bản B đổi duy nhất thời điểm sang hoàng hôn. Không cùng lúc đổi nhân vật, bối cảnh và hành động vì sẽ không biết yếu tố nào tạo khác biệt.", 'Write five lines: who, action, place, camera and invariants. Version A is a courier in a morning alley; B changes only the time to dusk. Do not change character, location and action together, or you cannot interpret the difference.'], 'L1-remix-brief.txt'),
          step(['Thực hiện hai phiên bản có kiểm soát', 'Run a controlled pair'], 'Text to Video', ['Dùng câu lệnh A; để có B, chỉ thay “buổi sáng” bằng “chạng vạng” (bản tiếng Anh: morning → dusk). Giữ model, tỷ lệ và thời lượng. Giới hạn hai lượt; có thể chỉ so hai bản prompt nếu chưa có credit. Lưu đầy đủ thông số, không chỉ câu lệnh.', 'Use prompt A; create B by replacing morning with dusk only. Keep model, ratio and duration fixed. Limit to two takes; compare the written prompts if credits are unavailable. Save settings as well as text.'], 'L1-remix-A-B.txt', 'One continuous five-second medium shot of an original adult courier in a quiet alley in soft morning light. The courier notices a faint amber glow coming from a closed blue mailbox and pauses. Locked eye-level camera. Keep the mailbox closed and the courier identity stable. No text, logos, dialogue, cuts or extra actions. Landscape 16:9.'),
          step(['Nhận xét bằng chi tiết nhìn thấy', 'Review observable differences'], 'Video player', ["Xem từng clip hai lượt: lần đầu theo dõi câu chuyện, lần sau nhìn tay, hộp thư và đường biên. Ghi một điểm tốt và một lỗi có timecode. Bản B có thể tốt hơn hoặc kém hơn bản A. Hãy đánh giá theo yêu cầu của bài thay vì độ phổ biến của prompt.", 'Watch twice: once for the story, once for hands, mailbox and edges. Record one strength and one timecoded issue. B need not outperform A, and a popular prompt does not guarantee views.'], 'L1-remix-review.txt'),
        ], ['Nêu được biến đã đổi và tác động quan sát được.', 'I can name the changed variable and its observed effect.'], ['Nếu clip quá nhiều hành động, chỉ giữ “notices and pauses”; đừng yêu cầu mở hộp, nhảy lên và chạy đi cùng lúc.', 'If the clip is overloaded, keep only “notices and pauses”; do not add opening, jumping and running together.']),
      lab('omni-presenter', ['Omni reference: nhân vật, bảng tin và đồ họa', 'Omni reference: presenter, sign and graphics'],
        ['Tải đúng ảnh người, bảng và logo vào từng ô của công cụ. Chữ khó tạo chính xác thì thêm sau bằng phần mềm dựng.', 'Assign assets to their roles in a presenter clip and decide which elements belong in post-production.'],
        ['Chân dung nhân vật hư cấu, thiết kế bảng sự kiện tự làm và biểu trưng bạn sở hữu. Không dùng logo đài truyền hình để giả tin thật.', 'A fictional portrait, a self-made event sign and a mark you own. Avoid presenting fictional footage as genuine news.'], [
          step(["Ghi rõ vai trò từng ảnh trước khi tải lên", 'Map assets before upload'], 'References / Omni', ["Đặt tên host.png, sign.png, brand.png. Tải từng file lên và ghi lại thẻ tham chiếu tương ứng trên giao diện. Nếu có menu @, chọn thẻ từ menu. Khi xóa hoặc thêm ảnh, kiểm tra lại vì số thứ tự có thể đổi.", 'Name files host.png, sign.png and brand.png. Upload in order and record the UI tag for each asset. Select tags from the @ menu when available. Recheck mapping after additions or deletions because numbering may change.'], 'L1-omni-map.txt'),
          step(["Nêu rõ cách sử dụng từng ảnh tham chiếu", 'Assign assets explicitly'], 'Omni / Reference to Video', ['Thay [HOST], [SIGN], [BRAND] bằng thẻ thật của công cụ. Chọn một cử chỉ đơn giản, không thêm thoại ở lượt đầu. Kiểm tra gương mặt, thứ tự chữ và vị trí bảng sau khi tạo.', 'Replace [HOST], [SIGN] and [BRAND] with actual tool asset tags. Start with a simple gesture and no speech. Check face, letter order and sign placement after generation.'], 'clips/L1-presenter.mp4', 'Use [HOST] only for the fictional presenter identity, [SIGN] for the event sign and [BRAND] for the small graphic in the lower corner. A five-second medium shot at an original studio desk. The presenter gives one small welcoming nod. Preserve the reference designs and their placement. Locked camera, no dialogue, no additional lettering or cuts. This is a fictional studio scene.'),
          step(["Thêm chữ và đồ họa trong phần mềm dựng", 'Use editing layers for exact lettering'], 'CapCut · Text / Overlay', ['Nếu chữ hoặc logo méo, tạo nền không chữ rồi chèn bảng PNG hoặc Text trong CapCut. Giữ cùng file đồ họa xuyên suốt; không tạo lại logo từng shot. Xem thử trên điện thoại để kiểm tra chữ có dễ đọc không.', 'If text or marks distort, generate a clean scene and place the PNG or Text layer in CapCut. Reuse the same graphic across shots instead of regenerating it. Check legibility at phone size.'], 'L1-presenter-edit + graphics/'),
        ], ["Phân biệt được thẻ tham chiếu và chữ gõ tay; chữ trên bảng hiển thị đúng và dễ đọc.", 'I can distinguish attached asset tags from typed text; the sign reads correctly.'], ['Nếu model không có Omni, ghép các ảnh thành một start frame trong trình sửa ảnh rồi tạo video; giữ đồ họa chính xác ở hậu kỳ.', 'Without Omni, compose one start frame in an image editor, then animate it; retain exact graphics in post.']),
      lab('photo-flight', ['Ảnh cá nhân thành chuyển động: bay lên và lỗi khuôn mặt', 'Animating a portrait: flight and identity drift'],
        ['Hiểu vì sao ảnh nghiêng hoặc mặt quá nhỏ không đủ để giữ nhân vật khi góc nhìn thay đổi.', 'Understand why a profile or tiny face may not support identity when the viewpoint changes.'],
        ['Ảnh tự chụp hoặc nhân vật hư cấu ở sân rộng; thêm một ảnh chính diện rõ mặt nếu được hỗ trợ.', 'Your own photo or a fictional person in an open courtyard; add a clear frontal reference if supported.'], [
          step(["Kiểm tra độ rõ của khuôn mặt trong ảnh", 'Inspect identity visibility'], 'Image viewer', ['Phóng ảnh lên, kiểm tra mắt, mũi, đường hàm có rõ không. Ghi góc mặt, phần cơ thể bị cắt, hướng sáng. Nếu ảnh chỉ thấy lưng, đừng kỳ vọng AI biết khuôn mặt phía trước; tạo ảnh chuẩn rõ hơn trước.', 'Zoom in and inspect eyes, nose and jaw. Record face angle, cropped body parts and lighting. A back view does not tell the model what the face looks like; prepare a clearer reference first.'], 'L1-photo-input-check.txt'),
          step(['Giới hạn chuyển động ở lượt đầu', 'Limit motion on the first take'], 'Image to Video', ['Thử nâng người lên một đoạn nhỏ thay vì bay vòng cả tòa nhà. Giữ góc mặt gần ảnh gốc. Nếu có reference phụ, gắn ảnh chính diện vào phần identity (ảnh giữ khuôn mặt); không chỉ nhắc tên file trong prompt.', 'Try a small lift rather than flying around a building. Keep the face angle near the original. If additional references are supported, attach the front portrait for identity; mentioning a filename does not attach it.'], 'clips/L1-lift.mp4', 'Use the supplied image as the opening composition. The same adult rises gently twenty centimetres above the courtyard floor, then holds still. Preserve the face angle, clothing and body proportions. A single continuous five-second shot with a locked camera. No spins, cuts, dialogue or background changes.'),
          step(["Xác định thời điểm khuôn mặt bắt đầu thay đổi", 'Find the onset of identity drift'], 'Video player', ['Dừng ở đầu, giữa và cuối; so cùng ảnh gốc. Nếu mặt đổi khi xoay, ghi timecode và giảm góc xoay hoặc thêm ảnh tham chiếu. Đừng kết luận giữ đúng 100% chỉ từ frame đầu.', 'Pause at the start, middle and end against the original. If identity changes during rotation, note the timecode and reduce rotation or add references. Do not infer perfect continuity from the first frame.'], 'L1-face-drift.txt'),
        ], ['Đã kiểm tra mặt ở ít nhất ba thời điểm.', 'Identity was checked at three or more points.'], ['Không có reference phụ thì dùng góc cố định và động tác ngắn; không sửa bằng một chuỗi tính từ “perfect face”.', 'Without additional references, use a fixed angle and short action; a string of “perfect face” adjectives will not provide missing visual information.']),
      lab('reference-analysis', ['Phân tích clip thành prompt ảnh và prompt chuyển động', 'Decompose a clip into image and motion prompts'],
        ['Viết riêng phần ảnh cần có và phần chuyển động. Dùng cách làm học được cho cảnh mới của bạn.', 'Separate static composition from temporal action and turn observations into an original exercise.'],
        ['Một clip ngắn của bạn hoặc được phép dùng, chỉ một bối cảnh; nếu chat không đọc video, dùng ba ảnh đầu/giữa/cuối và ghi chú.', 'One short original or licensed clip in a single setting; if chat cannot read video, use start/middle/end stills and notes.'], [
          step(['Chọn đoạn đủ ngắn để phân tích', 'Select a tractable excerpt'], 'CapCut', ['Cắt một đoạn có một hành động hoàn chỉnh. Ghi độ dài và các điểm cắt thật. Xuất ảnh đầu, giữa, cuối. Ảnh tĩnh không chứng minh được tốc độ hay âm thanh; ghi riêng điều bạn đã nghe/nhìn.', 'Trim a complete single action. Record duration and actual cuts, then export three stills. Stills do not establish speed or sound; separately note what you observed.'], 'refs/analysis-start-mid-end + L1-observation.txt'),
          step(['Yêu cầu hai đầu ra tách biệt', 'Request two separate outputs'], 'Chat assistant', ["Đính kèm ảnh hoặc video trước rồi gửi prompt. Đọc lại phần nào là quan sát và phần nào là phỏng đoán. Không chấp nhận tên lens (ống kính) hoặc thông số quay được đoán từ ảnh như dữ kiện.", 'Attach assets before sending the prompt. Distinguish observations from guesses. Do not treat inferred lens models or capture settings as verified facts.'], 'L1-two-prompts.txt', 'Analyze only the attached media and my notes. Separate visible facts from uncertain inferences. Describe framing, subject placement, light direction, action, camera movement and cuts. Then design a new scene about an original lantern repairer, not a reproduction of the reference. Return (1) an English prompt for one static starting image, and (2) an English motion prompt describing only what changes over time. If video or audio cannot be inspected, say so; do not infer timing from stills.'),
          step(["Tạo ảnh trước, rồi tạo chuyển động", 'Generate the still before motion'], 'Image generation → Image to Video', ["Dùng prompt tạo ảnh rồi chỉnh bố cục sao cho tư thế nhân vật phù hợp với hành động sắp diễn ra. Gắn ảnh đã chọn vào chế độ video và dùng prompt chuyển động. Lưu cả hai prompt cùng tên ảnh đầu vào để lần sau tái hiện được quá trình.", 'Run the image prompt and refine the composition until the action can plausibly begin. Attach the selected still in video mode and apply the motion prompt. Save both prompts with the input filename.'], 'L1-image-motion-pair/'),
        ], ['Có hai prompt khác chức năng và đầu vào tương ứng.', 'Two functionally distinct prompts and their inputs are recorded.'], ["Nếu prompt chuyển động quá dài, hãy tập trung vào hành động và chuyển động camera. Ảnh đầu vào đã cung cấp thông tin về ngoại hình nhân vật và bố cục.", 'If motion repeats every visual detail and adds many actions, retain action and camera instructions and let the image carry appearance.']),
    ],
    references: [
      lab('relight-character', ['Đặt nhân vật vào phòng tối và đổi ánh sáng', 'Place a character in a dark room and relight'],
        ['Giữ cùng khuôn mặt và quần áo; chỉnh ánh sáng trên người cho khớp căn phòng mới.', 'Preserve identity while adapting illumination to a new environment.'],
        ['Chân dung repairer.png và ảnh một phòng tối có cửa sổ bên trái.', 'repairer.png and a dark-room reference with a left-side window.'], [
          step(['Giữ nguyên nhân vật, chỉ đổi lighting (ánh sáng)', 'Lock identity, allow relighting'], 'Image editing', ["Ghi rõ không đổi tóc, hình mặt, áo; cho phép đổi độ sáng và bóng theo phòng. Giữ hướng cửa sổ nhất quán. Ảnh chân dung thường được chiếu sáng đều. Khi ghép vào phòng tối, cần chỉnh sáng tối trên nhân vật cho khớp với căn phòng, tránh cảm giác nhân vật bị dán lên nền.", 'Keep hair, facial shape and clothing fixed while allowing exposure and shadows to match the room. Maintain the window direction. Flat portrait lighting often needs adjustment to avoid a pasted-on appearance.'], 'L2-relight-constraints.txt'),
          step(['Tạo một khoảnh khắc phát hiện', 'Create a discovery moment'], 'Image editing · References', ['Đính kèm ảnh người và phòng; chọn khung 16:9. Không thêm nhiều đạo cụ ở lượt đầu. So bóng dưới cằm, bóng áo và ánh phản chiếu với hướng sáng chính.', 'Attach person and room, then choose 16:9. Avoid extra props on the first pass. Compare chin shadows, clothing shadows and reflections with the key light direction.'], 'frames/L2-discovery.png', 'Place the adult repairer from the identity reference inside the supplied dark workshop. The repairer has noticed an unlit lantern on a shelf. Preserve facial structure, short black hair, indigo jacket and beige apron. Relight the person to match cool window light from the left and weak warm bounce from the bench. Medium eye-level composition, natural skin texture, no additional characters or text.'),
          step(['Đánh giá đường biên và bóng', 'Review edges and shadows'], 'Image viewer', ['Xem viền tóc, vai, tiếp xúc chân với sàn và độ nét giữa người/nền. Nếu lệch, yêu cầu sửa ánh sáng vùng người mà giữ bố cục; lưu bản cũ để so.', 'Inspect hair/shoulder edges, floor contact and sharpness between person and background. If mismatched, edit subject lighting while preserving composition and keep the old version for comparison.'], 'L2-relight-review.txt'),
        ], ['Nhận ra cùng một người và giải thích được nguồn sáng.', 'The person remains recognizable and the light source is explainable.'], ["Nếu khuôn mặt quá tối, thêm ánh sáng bù nhẹ (fill light) từ phía đối diện để thấy rõ nét mặt; chưa cần thay đổi cả căn phòng.", 'If the face becomes unreadable, add a subtle opposite fill rather than redesigning the room.']),
      lab('asset-composite', ['Ghép người, đạo cụ và phương tiện', 'Combine character, prop and vehicle references'],
        ["Ghép nhiều thành phần vào cùng một cảnh, giữ đúng khuôn mặt nhân vật và thiết kế từng đồ vật.", 'Arrange several assets without mixing identity or redesigning them.'],
        ['Ảnh người sửa đèn, đèn đồng, xe đạp chở hàng và con hẻm tự tạo.', 'Original repairer, brass lantern, cargo bicycle and alley images.'], [
          step(['Vẽ sơ đồ trái/phải', 'Sketch left/right placement'], 'Paper / Notes', ["Vẽ sơ đồ vị trí của bốn thành phần trong khung hình: người bên trái, xe bên phải, đèn trên giá trước. Ghi tỉ lệ đèn nhỏ hơn đầu người. Sau khi tải ảnh lên, chọn đúng thẻ tham chiếu trên giao diện thay vì đoán số thứ tự.", 'Sketch four assets and the composition: person left, bicycle right, lantern on the front rack. Specify that the lantern is smaller than the head. Use actual uploaded tags rather than guessing indices.'], 'L2-composite-map.txt'),
          step(['Tạo ảnh ghép với vai trò riêng', 'Generate with distinct asset roles'], 'Image editing · References', ["Thay các nhãn ngoặc bằng thẻ. Kiểm tra tiếp xúc đèn/giá xe, ngón tay và bánh xe. Nếu quá khó, bắt đầu với hai thành phần, kiểm tra kết quả rồi thêm lần lượt các thành phần còn lại.", 'Replace bracketed labels with asset tags. Inspect lantern/rack contact, fingers and wheels. If overloaded, start with two assets, approve, then add one at a time.'], 'frames/L2-cargo.png', 'Use [PERSON] for identity and clothing, [LANTERN] for the small brass prop, [BICYCLE] for vehicle design and [ALLEY] for the environment. Wide eye-level shot: repairer stands screen-left beside the cargo bicycle on screen-right; one lantern rests securely on its front rack. Keep believable scale, shared dusk lighting and grounded contact shadows. Do not merge assets or invent extra wheels, hands or lanterns.'),
          step(['Ghi lỗi theo từng thành phần', 'Review each asset separately'], 'Image viewer', ["Lập bảng người/đèn/xe/nền, ghi đúng hoặc lỗi cụ thể. Chỉ sửa thành phần sai, đính kèm bản ghép gần nhất đã kiểm tra. Không lấy lỗi của người làm lý do tạo lại mọi thứ.", 'Use a person/prop/vehicle/environment table and record specific errors. Edit only the faulty element using the nearest approved composite, rather than regenerating the whole scene for one defect.'], 'L2-composite-review.txt'),
        ], ["Mỗi ảnh đầu vào có vai trò rõ ràng; vị trí từng thành phần trong ảnh kết quả đúng với sơ đồ.", 'Each asset has a distinct role and verifiable location.'], ["Nếu đạo cụ nhân đôi, ghi rõ “chỉ một chiếc đèn” và xóa bản thừa trong ảnh trước khi tạo chuyển động.", 'If the prop duplicates, specify “one lantern” and remove the extra in the still before animation.']),
      lab('wardrobe', ["Thay trang phục, giữ nguyên nhân vật", 'Change wardrobe while preserving identity'],
        ['Dùng một ảnh để giữ khuôn mặt, ảnh khác để lấy quần áo. So từng chi tiết áo sau khi tạo.', 'Separate identity and garment references; inspect garment details rather than overall appearance alone.'],
        ['Chân dung nguyên bản và ảnh áo khoác tự chụp, thấy rõ cổ/túi/khuy.', 'An original portrait and a clear garment photo showing collar, pockets and buttons.'], [
          step(['Chọn các chi tiết phải giữ', 'Choose garment invariants'], 'Notes', ['Ghi màu, chất liệu, số túi, kiểu cổ, vị trí khuy. Không yêu cầu logo nhỏ chính xác bằng lời nếu không có ảnh rõ. Chọn tư thế trung tính để so trang phục dễ hơn.', 'Record color, material, pocket count, collar and button placement. Tiny logos need a clear reference rather than words alone. Use a neutral pose for easier comparison.'], 'L2-garment-spec.txt'),
          step(['Thay đúng quần áo', 'Replace only clothing'], 'Image editing', ["Tải ảnh nhân vật trước, ảnh áo sau, rồi nêu rõ vai trò từng ảnh. Dùng prompt, kiểm tra mặt và vai. Sau khi chốt áo mới, dùng bản mới nhất cho toàn bộ shot tiếp theo, tránh xen ảnh mặc áo cũ.", 'Attach the person then garment with distinct roles. Apply the prompt and inspect face and shoulders. Once approved, use the new wardrobe consistently rather than mixing old clothing references.'], 'refs/repairer-new-jacket.png', 'Keep the adult identity, face, hair, body proportions and pose from [PERSON]. Replace only the jacket with the garment in [GARMENT], preserving its collar shape, two pockets, fabric texture and button arrangement. Fit it naturally with plausible folds. Plain neutral background, soft even light, no face changes, added accessories or lettering.'),
          step(['Chuyển sang bối cảnh phù hợp', 'Move to a suitable setting'], 'Image editing', ["Đưa nhân vật với trang phục đã chọn vào căn phòng hoặc hẻm. Đối chiếu thiết kế áo ở cả ảnh toàn cảnh và ảnh cận chi tiết. Với video sản phẩm, lưu ảnh đối chiếu để không mô tả thiết kế sai.", 'Place the approved dressed character in the room or alley. Compare wide and detail views of the garment. For product work, retain a comparison image to avoid misrepresenting the design.'], 'frames/L2-wardrobe-scene.png'),
        ], ['Mặt giữ nguyên; các chi tiết áo đã đối chiếu.', 'Identity is stable and garment features have been compared.'], ["Nếu áo đổi theo nền, dùng lại ảnh mẫu trang phục cùng bản người đã duyệt; bỏ mô tả thời trang mâu thuẫn.", 'If the garment changes with the background, reattach it with the approved person and remove conflicting fashion descriptions.']),
      lab('shot-sizes', ['Năm shot size (cỡ cảnh) và khi nào nên dùng', 'Five shot sizes and their story functions'],
        ["Chọn cỡ cảnh theo điều cần thể hiện: không gian, hành động, cảm xúc hoặc một chi tiết.", 'Choose framing for space, action, emotion or detail.'],
        ["Một ảnh người sửa đèn trong phòng, đã kiểm tra khuôn mặt, trang phục và thiết kế chiếc đèn.", 'One approved repairer-in-workshop frame.'], [
          step(['Lập bảng shot size', 'Build a shot-size table'], 'Notes', ["Extreme wide: giới thiệu căn phòng và người nhỏ trong đó. Wide shot: thấy nhân vật cùng nhiều không gian xung quanh; trong bài này có thể thấy toàn thân và chỗ đứng. Medium: nhìn tay và hành động ở bàn. Close-up: tập trung vào biểu cảm khuôn mặt. Extreme close-up: làm nổi bật một chi tiết như núm vặn của đèn hoặc mắt nhân vật. Mỗi cỡ cảnh thể hiện một loại thông tin; không mặc định cảnh cận đẹp hơn.", 'Extreme wide establishes room and a small figure. Wide shows full body and position. Medium reveals bench action and hands. Close-up reads expression. Extreme close-up isolates a switch or eye. Each serves information; closer is not automatically better.'], 'L2-shot-sizes.txt'),
          step(["Tạo năm cỡ cảnh từ cùng một bối cảnh", 'Create five views of one world'], 'Image editing', ['Chạy từng ảnh riêng, thay [FRAMING] bằng một cỡ trên và nêu chủ thể cần thấy. Đừng yêu cầu một ảnh ghép năm ô rồi dùng nguyên ảnh ghép để animate. Giữ hướng sáng và trạng thái đèn.', 'Generate separately, replacing [FRAMING] with a shot size and focal subject. Do not animate a five-panel contact sheet as one frame. Keep light direction and lantern state fixed.'], 'frames/L2-size-01–05.png', 'Reframe the approved workshop image as [FRAMING: e.g. close-up of the repairer face]. Preserve identity, indigo jacket, beige apron, brass lantern design, unlit state and blue window light from the left. Change framing only. Single image, landscape 16:9, no collage or new objects.'),
          step(['Xếp ba ảnh kể một ý', 'Sequence three views around one idea'], 'CapCut / Storyboard', ["Chọn wide shot để giới thiệu căn phòng, medium shot để thấy người thợ kiểm tra đèn, rồi close-up để thể hiện nét mặt hy vọng. Dựng mỗi ảnh 2 giây và xem không lời. Nếu người xem không hiểu chi tiết gì gây phản ứng, thêm một insert shot (shot riêng quay chi tiết chiếc đèn).", 'Choose wide for context, medium for inspection, close-up for hope. Hold each for two seconds in a silent animatic. If the cause of the reaction is unclear, add a lantern insert.'], 'exports/L2-framing-animatic.mp4'),
        ], ['Mỗi ảnh có mục đích kể chuyện và không đổi thiết kế.', 'Each view has a story purpose without redesigning assets.'], ['Nếu close-up cắt mất bộ phận quan trọng, nêu vùng phải nằm trong khung; tránh chỉ phóng ảnh wide quá mức.', 'If a close-up crops essential detail, specify what must remain visible rather than excessively enlarging a wide image.']),
      lab('camera-angles', ['Góc máy: ngang mắt, cao, thấp, từ trên và qua vai', 'Angles: eye level, high, low, overhead and over-shoulder'],
        ["Chọn vị trí camera phù hợp với điều bạn muốn người xem chú ý hoặc cảm nhận.", 'Make camera placement a deliberate storytelling choice.'],
        ["Sơ đồ căn phòng và vị trí người/đèn; giữ camera cùng một phía của đường nối giữa người và đèn để tránh đảo hướng nhìn.", 'Room layout and person/lantern positions; keep to one side of the action axis.'], [
          step(['Gắn ý nghĩa với góc nhìn', 'Connect angle to intention'], 'Storyboard', ["Eye level tạo cảm giác quan sát ngang hàng. High angle có thể khiến nhân vật trông nhỏ bé. Low angle có thể tạo cảm giác nhân vật hoặc đồ vật lớn hơn, nổi bật hơn. Bird’s-eye cho thấy sơ đồ không gian. Over-the-shoulder nhìn qua vai tới vật/người được chú ý. Ý nghĩa phụ thuộc bối cảnh, không phải quy tắc tuyệt đối.", 'Eye level suggests a peer viewpoint; high angles can emphasize vulnerability; low angles can emphasize stature; bird’s-eye reveals layout; over-the-shoulder relates an observer to a subject. Meaning depends on context, not an absolute rule.'], 'L2-angle-intentions.txt'),
          step(['Thử over-the-shoulder shot (góc nhìn qua vai)', 'Try an over-shoulder frame'], 'Image editing', ['Từ ảnh đã duyệt tạo over-the-shoulder shot; xác định vai trái/phải ở foreground (phần gần máy quay) và đèn ở đâu. Giữ đèn chưa sáng. Chạy một biến thể high angle để so thông tin khung hình, không đổi câu chuyện.', 'Create an over-shoulder view and specify which shoulder occupies the foreground and where the lantern sits. Keep it unlit. Test a high-angle variation to compare information without changing the story.'], 'frames/L2-OTS.png + L2-high.png', 'Reframe the same workshop from behind the repairer’s right shoulder. The shoulder is a soft foreground shape on screen-right, and the single unlit brass lantern is clearly visible on the bench at centre-left. Preserve room layout, costume and light direction. Eye-level over-the-shoulder composition, no new props.'),
          step(['Kiểm tra không gian khi đảo góc', 'Check geography across viewpoints'], 'Image viewer', ["So vị trí cửa sổ, bàn và hướng nhìn. Nếu một góc làm cửa sổ nhảy sang phía không thể có, hãy sửa ảnh đó trước khi tạo video. Vẽ mũi tên mắt nhìn tới đèn để phát hiện hướng nhìn sai.", 'Compare window, bench and eyeline. If a viewpoint moves the window impossibly, fix that image before video. Draw an eyeline arrow to identify gaze errors.'], 'L2-angle-continuity.txt'),
        ], ['Góc máy có lý do; sơ đồ phòng vẫn hợp lý.', 'The angle has a purpose and the room remains coherent.'], ['Nếu quay ra sau tạo một căn phòng mới, gắn thêm reference không gian; giảm mức đổi góc nếu chưa có đủ thông tin.', 'If the reverse view invents another room, attach an environment reference or reduce the viewpoint change.']),
      lab('scene-edit', ['Thêm nhân vật thứ hai và quay ra phía sau', 'Add a second character and build a reverse view'],
        ['Chỉnh một ảnh theo từng quyết định để tránh tích lũy lỗi.', 'Edit a scene one decision at a time to avoid compounding errors.'],
        ['Nhân vật thợ sửa đèn, chân dung khách hàng hư cấu và ảnh cửa tiệm.', 'Repairer, a fictional customer portrait and a workshop entrance reference.'], [
          step(['Thêm một mối quan hệ rõ ràng', 'Add a clear relationship'], 'Image editing', ["Đặt khách hàng phía cửa, người sửa đèn phía bàn. Chưa thêm tương tác tay; giữ khoảng cách rõ ràng giữa hai người. Hai nhân vật cần reference riêng và mô tả trang phục khác nhau.", 'Place the customer at the door and repairer at the bench. Avoid hand interaction initially and keep visible separation. Use distinct references and clothing descriptions.'], 'frames/L2-two-people.png', 'Keep the approved repairer on screen-left at the workbench. Add the adult customer from the second identity reference on screen-right near the open doorway, wearing the same green coat as that reference. They look toward each other; neither touches the other. Preserve the single lantern, room geometry and lighting. Medium-wide shot, no additional people.'),
          step(['Đổi góc, giữ hành động', 'Change viewpoint, retain the beat'], 'Image editing', ["Từ ảnh đã kiểm tra, yêu cầu nhìn từ sau khách hướng về người sửa đèn. Không đổi cảm xúc, vị trí hay trạng thái đèn trong cùng lần chỉnh. Nếu nền phía sau chưa có, tạo ảnh căn phòng riêng trước.", 'From the approved image, request a view behind the customer toward the repairer. Do not also change expression, position or lantern state. If the reverse environment is undefined, create a set reference first.'], 'frames/L2-reverse.png', 'Create a reverse over-the-shoulder view from behind the green-coated customer, looking toward the same repairer at the bench. Keep both people in their established positions, preserve the window and bench layout and the unlit lantern. Change only the viewpoint, with no new action.'),
          step(['Lưu nhánh chỉnh sửa', 'Preserve the edit lineage'], 'Project folder', ['Giữ base → two-people → reverse, ghi prompt và reference mỗi bước. Nếu reverse sai, quay về bản two-people đạt; đừng dùng một ảnh lỗi để tiếp tục sửa vô hạn.', 'Keep base → two-people → reverse with prompts and inputs. If the reverse fails, return to the approved two-person frame rather than endlessly building on a faulty image.'], 'L2-image-lineage.txt'),
        ], ['Hai nhân vật không trộn mặt; biết bản nào là đầu vào từng bước.', 'The two identities remain distinct and every edit has a known input.'], ["Nếu hướng nhìn của hai nhân vật không khớp, chỉ sửa eyeline của một người và giữ vị trí người còn lại.", 'If eyelines fail, edit one person’s gaze while preserving the other person’s position.']),
    ],
    motion: [
      lab('camera-vocabulary', ['Zoom, dolly, pan, tilt, orbit và handheld', 'Zoom, dolly, pan, tilt, orbit and handheld'],
        ['Phân biệt zoom (đổi focal length / tiêu cự), dolly (di chuyển máy quay) và pan/tilt (xoay máy quay).', 'Distinguish focal-length changes, camera translation and camera rotation.'],
        ['Một start frame dạng wide shot của người sửa đèn đứng giữa phòng, có foreground (phần gần máy quay) và background (phần phía sau).', 'One wide start frame of the repairer with visible foreground and background.'], [
          step(['Chọn đúng từ cho đúng chuyển động', 'Choose a precise movement term'], 'Notes', ['Zoom in/out làm khung nhìn hẹp/rộng hơn mà máy quay không cần tiến/lùi; dolly in/out là máy quay tiến/lùi thật, làm vị trí tương đối giữa vật gần và vật xa thay đổi. Pan left/right xoay ngang, tilt up/down xoay dọc, orbit đi vòng quanh chủ thể. Handheld là rung nhỏ có chủ đích. Model có thể diễn giải không đúng; luôn kiểm bằng clip.', 'Zoom changes field of view without requiring camera translation; dolly moves the camera and may change foreground/background relationships. Pan turns horizontally, tilt vertically, orbit moves around a subject and handheld adds controlled instability. Models may misinterpret these requests, so inspect results.'], 'L3-camera-glossary.txt'),
          step(['Tạo từng thử nghiệm riêng', 'Test one move at a time'], 'Image to Video', ["Giữ nguyên ảnh và hành động. Thay [MOVE] lần lượt bằng slow dolly in, slow pan left hoặc gentle orbit; chọn hai để thực hành, còn lại lập prompt. Ghi kỳ vọng phần nào sẽ được lộ ra; ảnh gốc không cho thấy toàn bộ không gian phía sau, nên AI có thể tự thêm bối cảnh khi camera di chuyển vòng quanh.", 'Keep the image and action fixed. Replace [MOVE] with slow dolly in, slow pan left or gentle orbit; practice two and prepare prompts for the rest. Record what should be revealed; an orbit may invent unseen space.'], 'L3-camera-tests/', 'Use the approved start frame. The repairer remains still beside the lantern. Camera: [MOVE], gradual and smooth over five seconds. Preserve identity, prop shape and room layout. One continuous shot with no cuts, no new actions and no dialogue. Stop before revealing any space not covered by my environment references.'),
          step(["Kiểm tra camera thực sự di chuyển như thế nào", 'Evaluate the actual move, not its label'], 'Video player', ['Theo dõi mép bàn và cửa sổ: chúng trượt hay chỉ phóng to? Ghi clip có thực hiện đúng yêu cầu không. Nếu muốn tilt lên thấy đèn trần, tạo reference có đèn trần để model có thông tin.', 'Track bench and window edges: do they shift relative to each other or only enlarge? Record adherence. To tilt up toward a ceiling light, provide a reference showing that light.'], 'L3-camera-observations.txt'),
        ], ['Giải thích được zoom khác dolly và chọn được một chuyển động phù hợp.', 'I can distinguish zoom from dolly and select a suitable move.'], ['Nếu máy quay tự cắt, ghi “one continuous shot” và bỏ yêu cầu nhiều góc trong cùng prompt.', 'If the camera cuts unexpectedly, specify one continuous shot and remove multiple viewpoint requests.']),
      lab('compound-speed', ['Kết hợp chuyển động và điều khiển tốc độ', 'Sequence movements and control speed'],
        ['Chia chuyển động thành pha rõ ràng thay vì yêu cầu nhiều việc đồng thời.', 'Break movement into explicit phases rather than simultaneous commands.'],
        ['Ảnh đèn trên bàn và reference trần nhà/cửa sổ; thời lượng được tài khoản hỗ trợ.', 'A lantern-on-bench image and ceiling/window references; a duration supported by your account.'], [
          step(['Vẽ đường đi của máy', 'Sketch the camera path'], 'Storyboard', ['Ví dụ A: đi vòng một góc nhỏ quanh đèn rồi tilt lên cửa sổ. Ví dụ B: dolly out rồi pan phải để thấy khách ở cửa. Vẽ điểm bắt đầu, chuyển pha và kết thúc; tránh đi xuyên bàn hoặc tường.', 'Example A: a small orbit around the lantern, then tilt toward the window. B: dolly out, then pan right to reveal the customer. Mark start, transition and end and avoid paths through furniture or walls.'], 'L3-camera-path.txt'),
          step(['Đặt trình tự và khoảng thời gian', 'Specify sequence and timing'], 'Image to Video', ['Dùng prompt 8 giây nếu công cụ hỗ trợ; nếu không, điều chỉnh hai pha theo thời lượng có sẵn. Không thêm hành động nhân vật khi đang kiểm chuyển động máy.', 'Use an eight-second prompt if supported, otherwise scale the phases to an available duration. Do not add character action while testing camera motion.'], 'clips/L3-compound.mp4', 'Single continuous eight-second shot of the same brass lantern in the reference workshop. 0–4s: the camera slowly orbits twenty degrees clockwise around the stationary lantern. 4–8s: it stops orbiting and gently tilts upward to reveal the existing window shown in the environment reference. Keep the lantern and room fixed. No cuts, sudden acceleration or new objects.'),
          step(['So chậm và nhanh với cùng quãng đường', 'Compare speed over the same path'], 'Prompt editor / Video player', ["Thử một bản chuyển động chậm để người xem có thời gian quan sát, và một bản nhanh nhưng mượt để tạo cảm giác khẩn trương. Nếu model không bám thời gian, tách thành hai shot và dựng. Không tăng tốc toàn clip nếu làm động tác người trở nên vô lý.", 'A slow deliberate move supports observation; a brisk smooth move can suggest urgency. If timing fails, split into two shots and edit. Do not speed up the entire clip if human motion becomes implausible.'], 'L3-speed-review.txt'),
        ], ["Hai giai đoạn diễn ra đúng thứ tự; camera không đi xuyên đồ vật.", 'The two phases read in sequence without impossible camera travel.'], ['Nếu orbit và tilt xảy ra cùng lúc, thử từng pha riêng để xác định phần thất bại rồi đơn giản hóa.', 'If orbit and tilt happen simultaneously, test phases separately to isolate the failure, then simplify.']),
      lab('model-tests', ["So sánh model qua diễn xuất và hành động", 'Compare models with emotion and action tests'],
        ['Chọn model theo yêu cầu shot, không theo một bảng xếp hạng chung.', 'Choose a model for a shot’s requirements rather than a universal ranking.'],
        ['Hai model bạn đã có quyền dùng; cùng ảnh và prompt, ghi rõ khác biệt thiết lập.', 'Two models already available to you; matched images and prompts with setting differences recorded.'], [
          step(['Tạo bài test cảm xúc', 'Build an emotion test'], 'Image to Video', ["Dùng close-up của người sửa đèn: từ lo lắng sang nhẹ nhõm khi đèn bật. Không thêm hét, khóc và quay đầu cùng lúc. Chấm độ tự nhiên, chuyển biến cảm xúc và giữ đúng khuôn mặt; có thể dừng ở hai lượt.", 'Use a repairer close-up shifting from concern to relief as the light returns. Avoid adding shouting, crying and head turning together. Score naturalness, emotional change and identity, with an optional two-attempt limit.'], 'clips/L3-emotion-A-B/', 'Close-up of the same adult repairer. Over five seconds, a tense brow relaxes and a small relieved smile appears as warm light softly reflects on the face. Very slow camera push-in. Subtle breathing, believable eye movement, no dialogue, tears, head turns or exaggerated expression.'),
          step(['Tạo bài test hành động riêng', 'Build a separate action test'], 'Image to Video', ['Dùng hai nhân vật hư cấu tập đối luyện gậy xốp, không va chạm thật. Quan sát đường đi đạo cụ, nhịp tránh và chân trụ. Nếu không muốn cảnh đối luyện, thay bằng đỡ chiếc hộp rơi; giữ tiêu chí trọng lượng và tiếp xúc.', 'Use two fictional adults rehearsing with foam staffs, without real impact. Inspect prop paths, avoidance timing and planted feet. A falling-box catch can substitute while preserving weight/contact criteria.'], 'clips/L3-action-A-B/', 'Two fictional adult performers rehearse one slow foam-staff exchange in an empty training room. The left performer makes one controlled horizontal sweep; the right performer steps back once to avoid it. Both finish balanced with feet on the floor. Five seconds, medium-wide framing, subtle handheld camera, no injury, cuts, extra strikes or changing props.'),
          step(["Đánh giá kết quả và chi phí cho phần video dùng được", 'Score fitness and usable cost'], 'Notes', ["Lập bảng so sánh gồm: model, độ nhất quán của khuôn mặt, hành động, tính hợp lý của chuyển động, camera, âm thanh, chi phí và số giây dùng được. Chấm từng mục từ 0 đến 2 và ghi thời điểm làm căn cứ. Chi phí mỗi giây dùng được = tổng credit thử / giây đã chọn; nếu chưa có đoạn dùng được thì ghi chưa tính được.", 'Use model | identity | action | physics | camera | audio | cost | usable seconds. Score 0–2 with timecodes. Cost per usable second equals total trial credits divided by selected duration; if nothing is usable, mark it undefined.'], 'L3-model-scorecard.txt'),
        ], ['Có bằng chứng từng tiêu chí; không kết luận tuyệt đối từ một lần tạo.', 'Each score has evidence and one take is not treated as a universal result.'], ['Nếu hai model không có cùng thời lượng/độ phân giải, ghi rõ khác biệt và chỉ so đoạn tương đương.', 'If duration or resolution differs, document it and compare equivalent portions only.']),
      lab('endpoints-transform', ['Frame đầu/cuối: đổi góc và biến đổi vật thể', 'Endpoints: viewpoint changes and object transformation'],
        ['Phân biệt ràng buộc điểm đầu/cuối với kiểm soát toàn bộ chuyển động ở giữa.', 'Distinguish endpoint constraints from control over every intermediate frame.'],
        ['Hai ảnh cùng tỷ lệ; A là đèn tắt, B là đèn sáng. Bài mở rộng dùng giấy phẳng → chim giấy.', 'Two same-ratio images: unlit lantern A and lit lantern B. An extension uses flat paper → folded paper bird.'], [
          step(['Kiểm tra độ tương thích hai ảnh', 'Check endpoint compatibility'], 'Image viewer', ["So vị trí, góc nhìn, kích thước và ánh sáng. Với bài đổi góc, giữ vật thể và chỉ đổi camera. Với biến hình, giữ camera đứng yên và chỉ đổi vật thể. Đổi cả camera, người và nền sẽ khiến chuyển động giữa hai ảnh khó kiểm soát.", 'Compare position, angle, scale and lighting. For viewpoint changes, hold the object fixed; for transformations, hold the camera fixed. Changing camera, person and set together makes interpolation unpredictable.'], 'L3-endpoint-pair.txt'),
          step(['Thử biến đổi có ràng buộc', 'Try a constrained transformation'], 'Start / End frame', ["Đặt đúng A/B và dùng prompt. Dùng ảnh chim giấy đã kiểm tra làm frame kết thúc. Nếu tính năng không có, dựng hai ảnh với điểm cắt hoặc dissolve trong CapCut và ghi đó là hậu kỳ, để phân biệt với chuyển động do AI tạo ra.", 'Attach A/B correctly and use the prompt. End on the approved paper-bird image. Without endpoint support, cut or dissolve between stills in CapCut and label it an edit, not generated transformation.'], 'clips/L3-paper-transform.mp4', 'Use the supplied flat-paper image as the start and the supplied folded-paper-bird image as the end. Over five seconds the single sheet folds gradually into the same paper bird, staying on the same tabletop. Locked camera, unchanged background and lighting. No extra paper, hands, smoke or cuts. Keep the intermediate motion physically readable.'),
          step(['Duyệt cả phần ở giữa', 'Inspect the middle as well as endpoints'], 'Video player', ["Xem chậm đoạn 1–4 giây: giấy có nhân đôi, xuyên bàn, nhảy hình không? Dù ảnh đầu và cuối đúng, clip vẫn cần sửa nếu phần chuyển động ở giữa có lỗi. Nếu chuyển quá khó, chia thành ba trạng thái hoặc dùng cắt dựng.", 'Inspect seconds 1–4 for duplication, table penetration or abrupt morphs. Correct endpoints do not validate a broken middle. If too difficult, introduce an intermediate state or use editing.'], 'L3-interpolation-review.txt'),
        ], ['Đã duyệt đầu, giữa, cuối và nêu rõ mức kiểm soát thực tế.', 'Start, middle and end were checked and actual control is documented.'], ["Nếu model chỉ làm mờ ảnh này rồi hiện dần ảnh kia, đơn giản hóa biến đổi hoặc dùng một hành động cơ học dễ hơn như bật công tắc.", 'If the model only dissolves between images, simplify the transformation or try an easier mechanical action such as a switch.']),
      lab('dialogue-multishot', ['Đối thoại nhiều góc: toàn cảnh, người nói và phản ứng', 'Dialogue coverage: master, speaker and reaction'],
        ["Chừa thời gian ngắt nghỉ trong lời thoại và cho thấy phản ứng của người nghe.", 'Allow dialogue breathing room and use reactions to carry the story.'],
        ['Hai nhân vật nguyên bản, một không gian; mỗi người một câu ngắn.', 'Two original characters in one setting, with one short line each.'], [
          step(['Đọc thoại trước khi đặt thời lượng', 'Time speech before allocating duration'], 'Voice recorder / Notes', ["Tự đọc hai câu với ngắt nghỉ: “Đèn còn sửa được không?” và “Hãy cho tôi một phút.” Đo thời gian thực, chừa thời gian cho ánh mắt và phản ứng của nhân vật. Nếu đọc đã hết thời lượng, rút lời hoặc tăng thời gian được hỗ trợ; đừng ép vào 5 giây.", 'Read “Can you repair it?” and “Give me a minute” with pauses. Measure delivery and allow looks/reactions. If speech fills the entire allocation, shorten it or use a longer supported duration rather than squeezing it into five seconds.'], 'L3-dialogue-timing.txt'),
          step(['Viết shot theo người đang nói', 'Write shots around speaker turns'], 'Multi-shot / Separate generations', ["Dùng prompt, thay câu thoại đúng ngôn ngữ. Nếu công cụ không hỗ trợ clip dài 15 giây, tạo từng shot rồi ghép. Tên nhân vật và vai trò reference phải nhất quán; không để cả hai cùng nói một câu.", 'Use the prompt with your chosen language. If fifteen seconds are unsupported, generate separate shots and assemble. Keep character names and reference roles consistent; do not assign a line to both people.'], 'L3-dialogue-prompts.txt', 'A quiet conversation between the green-coated customer and indigo-jacketed repairer in the same workshop. 0–3s: medium-wide master establishing both people and the unlit lantern. 3–7s: customer close-up, gently asks "Can you repair it?" 7–11s: repairer close-up, pauses then replies "Give me a minute." 11–15s: silent reaction from the customer. Keep the established screen directions, natural lip motion and a calm pace. No overlapping speech or unplanned cuts.'),
          step(['Sửa nhịp bằng hình lẫn tiếng', 'Repair pacing in picture and sound'], 'CapCut', ["Nghe riêng âm thanh để phát hiện lời thoại quá dồn dập. Sau đó xem không tiếng để kiểm tra hướng nhìn và phản ứng. Thêm reaction shot hoặc giữ khoảng im lặng thay vì lặp thoại. Nếu tiếng Việt sai, dùng lời dẫn tự thu hoặc dựng lại câu ngắn, không đánh dấu đạt chỉ vì miệng cử động.", 'Listen without picture for rushed speech, then watch muted for eyelines and reactions. Add a reaction or silence rather than repeating lines. If pronunciation fails, use a clean recorded voice-over or shorter regenerated line; moving lips alone are insufficient.'], 'L3-dialogue-review.txt'),
        ], ['Người nói đúng lượt, lời rõ và có khoảng phản ứng.', 'Turns are assigned correctly, speech is clear and reactions have room.'], ["Nếu model tự cắt sai thời điểm, tách shot; tạo từng shot riêng rồi chủ động chọn điểm cắt trong phần mềm dựng.", 'If cuts ignore timing, generate separate shots; manual editing may be more dependable than adding more timecodes.']),
      lab('debug-fantasy', ["Sửa lỗi cảnh kỳ ảo: đôi mắt, tỉ lệ và góc nhìn POV", 'Debug fantasy shots: anatomy, scale and POV'],
        ['Biến một lỗi nhìn thấy thành ràng buộc cụ thể mà không viết lại toàn bộ cảnh.', 'Translate a visible defect into a specific constraint without rewriting everything.'],
        ['Storyboard một người đưa thư gặp robot gác cổng có một lens (ống kính của camera) ở ngực; không dùng nhân vật phim có sẵn.', 'An original storyboard of a courier meeting a gatekeeper robot with one chest-mounted optical lens.'], [
          step(['Liệt kê hình dạng không được đổi', 'List design invariants'], 'Notes', ['Robot cao gấp đôi người, một lens ở giữa ngực, không mắt người. Người có mắt tự nhiên không phát sáng. Shot 1 toàn cảnh, shot 2 high angle nhìn người, shot 3 low angle robot, shot 4 POV robot. Vẽ POV rõ để tránh thêm con robot thứ hai.', 'Robot twice human height, one central chest lens, no human eyes. The courier has natural non-glowing eyes. Plan wide, high-angle courier, low-angle robot and robot-POV views. Sketch POV to avoid accidentally adding a second robot.'], 'L3-fantasy-invariants.txt'),
          step(['Sửa đúng lỗi đầu tiên', 'Fix the first concrete failure'], 'Prompt editor', ['Ví dụ lỗi: model thêm hai mắt lên đầu robot. Dùng prompt sửa với reference thiết kế gốc. Nếu có ô negative prompt dùng ô đó; nếu không, viết ràng buộc trong prompt chính. Ràng buộc không bảo đảm thành công nên vẫn cần duyệt.', 'Example failure: the model adds two eyes to the robot head. Use the repair prompt with the original design. Use a negative field if available, otherwise place constraints in the main prompt. Constraints still require verification.'], 'L3-fantasy-fix.txt', 'Revise only robot anatomy in this shot. Match the supplied robot design: a blank head plate and exactly one circular optical lens centred on the chest. Preserve the courier, scale, staging, camera and timing. The courier has ordinary unlit human eyes. Do not add human eyes, extra lenses or glowing facial features. Start from the supplied approved composition.'),
          step(["Thử góc nhìn POV để làm rõ phản ứng", 'Try POV when a reaction shot feels flat'], 'Storyboard / Image editing', ["Đổi shot cuối thành góc nhìn từ robot xuống người, giữ vị trí và eyeline. Đây là quyết định kể chuyện riêng, không thực hiện cùng lần sửa cấu tạo nhân vật nếu muốn biết thay đổi nào có tác dụng. Lưu kết quả trước và sau khi sửa, kèm thời điểm của đoạn dùng được.", 'Change the final shot to the robot’s view down toward the courier while preserving positions and eyelines. Treat this as a separate story decision from anatomy repair so its effect can be evaluated. Save before/after and usable ranges.'], 'L3-fantasy-review.txt'),
        ], ['Có lỗi cụ thể, prompt sửa giới hạn và kiểm lại đầu ra.', 'A concrete defect, bounded revision and output review are recorded.'], ["Nếu nhiều lỗi cùng lúc, sửa ảnh đầu trước; hãy chỉnh bố cục trước khi viết thêm yêu cầu chuyển động.", 'If many defects coincide, repair the input frame rather than burying a broken composition under a long motion prompt.']),
      lab('draft-budget', ['Tạo nháp, giới hạn lượt thử và nâng chất lượng', 'Draft settings, attempt limits and quality upgrades'],
        ['Tối ưu số đoạn dùng được thay vì số clip được tạo.', 'Optimize usable footage rather than generation count.'],
        ['Bảng giá hiện trong tài khoản và shot list của bạn; không dùng giá minh họa như báo giá hiện hành.', 'Current account pricing and your shot list; illustrative prices are not current quotes.'], [
          step(["Chọn chất lượng bản nháp đủ để kiểm tra lỗi", 'Choose a reviewable draft setting'], 'Generation settings', ["Nếu có bản nháp độ phân giải thấp hoặc model nhanh, kiểm tra giá hiển thị rồi thử. Chất lượng phải đủ thấy lỗi mặt/tay. Đặt giới hạn credit và số lượt tối đa mỗi shot; khi đạt giới hạn, hãy chỉnh ảnh đầu vào hoặc đổi cách dựng trước khi thử tiếp.", 'If low-resolution or fast drafts exist, inspect displayed cost before trying. The draft must still reveal face/hand defects. Set per-shot credit and attempt caps; stop at the cap to revise input or editing strategy.'], 'L3-budget.txt'),
          step(['Ghi nhật ký từng take', 'Log every take'], 'Notes', ["Mỗi dòng: shot, model, thiết lập, ảnh đầu vào, phiên bản prompt, chi phí, thời gian chờ, giây dùng được, lý do giữ/bỏ. Ghi rõ trạng thái: đang chờ (queued), thất bại (failed) hoặc hoàn tất (completed). Chỉ tính là tư liệu sau khi video đã tạo xong và có thể xem được.", 'Record shot, model, settings, inputs, prompt version, cost, wait, usable seconds and keep/reject reason. Distinguish queued, failed and completed states. A queued tile is not footage.'], 'L3-take-ledger.txt'),
          step(['Duyệt lại bản chất lượng cao', 'Re-review higher-quality generations'], 'Video player', ["Chỉ nâng chất lượng sau khi bố cục và hành động của shot đã đạt yêu cầu. Lượt tạo lại có thể đổi diễn xuất hoặc thời điểm, dù prompt không đổi. Giữ bản nháp tốt, so bản mới và cập nhật kế hoạch dựng; không tự thay clip chỉ vì số pixel cao hơn.", 'Upgrade after resolving shot structure. Regeneration can change performance or timing even with the same prompt. Preserve the good draft, compare the new take and update the edit plan; do not replace it solely for more pixels.'], 'L3-final-take-choice.txt'),
        ], ["Đã đặt giới hạn số lần thử và chọn clip dựa trên phần video dùng được.", 'An attempt cap and a usable-footage-based choice are recorded.'], ["Nếu không bản nào đạt sau số lần thử đã đặt, giảm hành động hoặc dựng ngắn hơn thay vì tiếp tục vô hạn.", 'If nothing passes within the cap, simplify the action or shorten the edit instead of generating indefinitely.']),
    ],
    review: [
      lab('reference-pack', ['Bộ tham chiếu nhân vật, phòng và frame đầu', 'Character, set and start-frame reference pack'],
        ['Ghi rõ ảnh nào dùng để giữ khuôn mặt, ảnh nào cho quần áo, ảnh nào cho căn phòng. Đừng dùng các ảnh có chi tiết trái ngược nhau.', 'Separate identity, costume, geography and composition references to avoid conflicting guidance.'],
        ['Chân dung, góc nghiêng, ảnh trang phục và sơ đồ phòng của cùng một dự án.', 'Portrait, side view, clothing and room layout from one project.'], [
          step(['Ưu tiên mặt rõ hơn ảnh toàn thân nhỏ', 'Prioritize clear faces over tiny full-body faces'], 'Image editing', ['Tạo ảnh chính diện và 3/4 riêng, đủ chi tiết. Ảnh trang phục có thể chỉ từ vai xuống nếu một contact sheet (bảng ghép nhiều ảnh) chứa nhiều khuôn mặt khiến model nhầm. Không cắt đầu mọi ảnh theo một công thức: cần ít nhất một reference mặt rõ và mỗi file có vai trò.', 'Create separate front and three-quarter portraits with readable detail. A costume reference can show shoulders down if a contact sheet’s multiple faces confuse the model. Do not remove heads indiscriminately: retain a clear face reference and assign each file a role.'], 'refs/face-front.png + face-three-quarter.png + costume.png', 'Create a three-quarter portrait of the same fictional repairer using the identity reference. Preserve facial structure, short black hair and natural skin detail. Neutral expression, plain background and even soft light. Show only one view in this image. Do not redesign the face, age or hairstyle.'),
          step(['Giữ bố trí căn phòng bằng bản vẽ đơn giản', 'Lock the set with a layout'], 'Image editing / Sketch', ["Ghi cửa bên phải, cửa sổ trái, bàn giữa; tạo một wide reference thấy đủ các điểm này. Vẽ chỗ đứng nhân vật và hướng nhìn máy. Tránh dùng các ảnh căn phòng có cách bố trí khác nhau, dù từng ảnh trông đẹp.", 'Record door right, window left and central bench; create a wide reference showing these landmarks. Sketch character positions and camera direction. Avoid three attractive but incompatible room references.'], 'refs/set-wide.png + set-plan.png'),
          step(['Chuẩn bị manifest (danh sách file đầu vào) cho mỗi shot', 'Prepare a per-shot manifest'], 'Notes / Omni', ["Ví dụ đoạn S01: tải face-front để giữ đúng khuôn mặt, costume để giữ áo, set-wide để giữ phòng, S01-start để làm ảnh mở đầu. Kiểm đúng tên file trong từng ô. Nếu đổi ảnh mở đầu, kiểm lại các ảnh còn lại trước khi tạo.", 'For S01, use face-front for identity, costume for clothing, set-wide for geography and S01-start for composition. Record actual tags and attach only needed files. Recheck all roles when changing the start frame.'], 'L4-reference-manifest.txt'),
        ], ['Không có reference mâu thuẫn và mỗi file có vai trò duy nhất dễ hiểu.', 'References are compatible and each file has a clear role.'], ['Nếu model chọn mặt nhỏ trong sheet, tách chân dung riêng và bỏ khuôn mặt trùng khỏi ảnh trang phục.', 'If the model uses a tiny sheet face, separate the portrait and remove redundant faces from the costume reference.']),
      lab('director-brief', ["Chỉ đạo cảnh quay: bố cục, nhịp hành động và diễn xuất", 'Director prompt: staging, beats, performance and weight'],
        ["Mô tả diễn biến của cảnh theo thứ tự: nhân vật làm gì, vì sao và người còn lại phản ứng thế nào.", 'Write a longer scene as motivated actions and reactions rather than adjectives.'],
        ['Bộ ảnh mẫu đã chọn, không đổi giữa các lượt thử; cảnh khách đặt hộp nặng lên bàn và người sửa đèn phản ứng.', 'Locked references; a customer sets a heavy box on a bench and the repairer reacts.'], [
          step(['Điền chín phần của brief', 'Fill nine brief sections'], 'Notes', ["Viết tổng quan; vai trò từng ảnh và clip tham chiếu; vị trí trái/phải; camera; mốc hành động; nét mặt/nhịp thở; tiếp xúc/trọng lượng; ánh sáng/âm thanh; giới hạn. Với cảnh dài, mỗi pha phải đủ thời gian; không bắt buộc tạo một lượt 30 giây nếu tài khoản chỉ cho clip ngắn.", 'Write overview; asset roles; screen positions; camera; action beats; expression/breath; contact/weight; light/sound; constraints. Allow time for each phase. A thirty-second single generation is unnecessary when shorter clips are supported.'], 'L4-director-brief.txt'),
          step(['Viết nhịp đặt vật và phản ứng', 'Specify contact and reaction beats'], 'Video generation', ["Dùng prompt cho 10 giây nếu hỗ trợ hoặc tách thành hai clip. Để chiếc hộp trông có sức nặng, cần mô tả tốc độ hạ hộp, thời điểm tay dừng lại và cách cơ thể giữ thăng bằng. Đừng dùng “heavy” một mình để thay mô tả diễn biến.", 'Use ten seconds if supported or split into two clips. Weight should read through lowering speed, hands stopping and body stabilization. The word “heavy” alone does not describe the action.'], 'clips/L4-weight-take01.mp4', 'Scene: the customer delivers a heavy wooden box to the repairer. Use the supplied identity and workshop references in their assigned roles. Customer screen-right, repairer screen-left. 0–4s: medium-wide view, customer slowly lowers the box with both hands; it stops firmly on the bench before the hands release. 4–7s: cut to repairer close-up, eyebrows lift slightly, then a short thoughtful pause. 7–10s: insert of the closed stationary box. Shared dusk lighting, one quiet contact sound, no dialogue. Keep one box, grounded feet, continuous hand contact until set-down and no extra motion.'),
          step(['Sửa phản ứng hoặc vật lý từng lượt', 'Revise performance or physics separately'], 'Video player / Prompt editor', ["Nếu hộp xuyên bàn, sửa phần tiếp xúc giữa hộp và mặt bàn trong shot đầu. Nếu người sửa đèn nhìn vô cảm, mô tả một phản ứng cụ thể, không thêm lời thoại để che. Nếu một người nói dài mà thiếu góc đối phương, cắt sang phản ứng. Lưu timecode trước/sau.", 'If the box penetrates the bench, repair the first-shot contact. If the repairer feels blank, specify one reaction rather than masking it with speech. If one speaker dominates, cut to the listener’s response. Save before/after timecodes.'], 'L4-performance-revision.txt'),
        ], ['Động tác có chuẩn bị, tiếp xúc, dừng và phản ứng rõ.', 'The action has preparation, contact, settling and a readable reaction.'], ["Nếu tay vẫn lỗi, bắt đầu sau khi hộp đã nằm trên bàn và dùng cảnh cận chiếc hộp kết hợp với biểu cảm nhân vật để kể tiếp.", 'If hands keep failing, begin with the box already on the bench and tell the beat through an insert and reaction.']),
      lab('voice-reference', ['Giữ một giọng qua nhiều clip', 'Maintain one voice across clips'],
        ['Tạo mẫu giọng sạch, gắn đúng reference và kiểm phát âm độc lập với hình.', 'Prepare a clean voice sample, attach it correctly and check pronunciation separately from visuals.'],
        ['Giọng tự thu hoặc được cho phép sử dụng, một câu mẫu rõ không lẫn nhạc.', 'Your own or an authorized voice, with a clear sample and no music.'], [
          step(['Tách đoạn chỉ có người cần giữ giọng', 'Isolate the intended speaker'], 'CapCut · Extract audio', ['Nhập clip, tách âm thanh và cắt riêng đoạn một người nói. Nghe xem còn nhạc, tiếng phòng hay giọng khác không. Lưu WAV nếu tool nhận audio; nếu tool chỉ nhận video, xuất video nền đen chứa chính đoạn giọng theo định dạng được hỗ trợ.', 'Import, extract audio and isolate one speaker. Listen for music, room noise or another voice. Save WAV if accepted; if the tool only accepts video references, export a supported black-background video containing the same voice segment.'], 'refs/voice-clean.wav or voice-reference.mp4'),
          step(['Gắn giọng vào lời thoại cụ thể', 'Bind the voice to a specific line'], 'Audio / Video reference', ['Gắn file qua UI, thay [VOICE] bằng thẻ thực. Chỉ yêu cầu một câu ngắn và một người. Nếu không hỗ trợ giọng tham chiếu, dùng bản thu ở hậu kỳ làm lời dẫn ngoài hình; không coi tên file gõ trong prompt là đã gắn giọng.', 'Attach the file in the UI and replace [VOICE] with the actual asset tag. Use one short line and one speaker. Without voice references, use your recording as off-screen narration; typing a filename is not attachment.'], 'L4-voice-prompt.txt', 'Use [VOICE] only as the authorized voice reference for the repairer, not for visual identity or scene content. The repairer softly says, in Vietnamese, "Ánh sáng đã trở lại." Use a natural pause before the line, calm delivery and clear pronunciation. Preserve the visual character and workshop references. No other speakers, music or additional words.'),
          step(['Nghe từng từ và so âm sắc', 'Check words and vocal consistency'], 'Headphones / CapCut', ["Nghe không nhìn hình; ghi chữ sai, âm tiết nuốt và chỗ giọng đổi. So câu mới với mẫu ở cùng âm lượng. Nếu phát âm sai, rút câu hoặc dùng giọng tự thu; tăng độ phân giải hình ảnh không sửa được lỗi phát âm. Kiểm lip-sync riêng nếu nhân vật nói trong hình.", 'Listen without picture and record wrong words, swallowed syllables or voice shifts. Compare at similar loudness. Shorten the line or use the recording if pronunciation fails; higher image resolution will not fix speech. Check lip sync separately for on-screen dialogue.'], 'L4-voice-QC.txt'),
        ], ['Có mẫu sạch, vai trò reference và kiểm tra phát âm/miệng riêng.', 'A clean sample, explicit reference role and separate speech/lip checks are recorded.'], ["Nếu kết quả lẫn hai giọng, hãy cắt lại mẫu để chỉ còn một người nói. Bạn cũng có thể thay giọng do AI tạo bằng lời dẫn tự thu.", 'If voices mix, isolate a single speaker or replace generated speech with voice-over.']),
      lab('upscale-choice', ['Giữ diễn xuất: upscale hay tạo lại?', 'Preserve performance: upscale or regenerate?'],
        ['Cân nhắc giữa diễn xuất tự nhiên và độ chi tiết của hình ảnh. Upscale giúp tăng độ phân giải, không sửa được chuyển động sai.', 'Balance a strong performance against detail without treating upscale as motion repair.'],
        ['Một clip nháp có diễn xuất đạt yêu cầu và, nếu có, một phiên bản tạo lại ở chất lượng cao hơn.', 'A well-performed draft and, if available, a higher-quality regeneration.'], [
          step(['Chọn đoạn diễn xuất cần giữ lại', 'Identify the performance worth keeping'], 'Video player', ['Ghi timecode nụ cười, cú đặt đồ hoặc câu thoại khớp nhịp. Giữ nguyên bản nháp. Nếu tạo lại làm mất khoảnh khắc này, không thay bản cũ chỉ vì độ phân giải cao hơn.', 'Record the smile, contact or line timing that works. Preserve the original draft. If regeneration loses that moment, do not replace the draft solely for resolution.'], 'L4-performance-lock.txt'),
          step(['Thử một bản upscale', 'Try one upscale version'], 'Upscale tool', ['Nếu có công cụ phù hợp, xem giá trước và xuất sang file mới. Chọn độ phân giải đủ cho đầu ra, không mặc định 4K. Nếu không có, dùng bản nguồn trong timeline và đánh giá ở kích thước xem thực tế.', 'If available, inspect cost and export an upscale to a new file. Choose a useful delivery size rather than automatically requesting 4K. Without access, evaluate the source at its intended viewing size.'], 'clips/L4-upscaled-candidate.mp4'),
          step(['So sánh khuôn mặt, chi tiết hình ảnh và âm thanh', 'Compare faces, texture, edges and sound'], 'Video player', ['Xem bản gốc và bản upscale ở cùng kích thước. Kiểm tra da có bị làm mịn quá mức, xuất hiện chi tiết lạ, quầng sáng ở viền (halo), nhấp nháy (flicker), hoặc âm thanh lệch với hình không. Upscale có thể bổ sung chi tiết do AI suy đoán, nhưng không xác nhận được chi tiết gốc và không sửa được diễn xuất sai. Ghi lại lý do chọn phiên bản cuối.', 'Compare at the same display size for skin smoothing, invented texture, halos, flicker and duration/audio drift. Upscale cannot recover nonexistent detail or repair bad acting. Record your final choice.'], 'L4-upscale-decision.txt'),
        ], ['Giữ bản gốc và chọn bằng cả diễn xuất lẫn chất lượng hình.', 'The original is retained and selection considers both performance and image quality.'], ['Nếu upscale làm mặt như nhựa, dùng mức nhẹ hơn hoặc giữ bản gốc; không tiếp tục nâng nhiều lần.', 'If skin becomes plastic, reduce processing or retain the original rather than repeatedly upscaling.']),
      lab('live-vfx', ['Quay thật rồi đổi bối cảnh hoặc thêm hiệu ứng', 'Live-action plates: replace a set or add an effect'],
        ['Xác định phần diễn xuất cần giữ và phần hình ảnh muốn thay đổi. Sau khi tạo, kiểm tra nhân vật, chuyển động camera và bố trí không gian có còn nhất quán không.', 'Separate the original performance from allowed edits and check person, camera and scene continuity.'],
        ['Clip bạn tự quay, một diễn viên, ánh sáng ổn định; reference phòng đích nếu đổi bối cảnh.', 'Your own single-performer clip with stable lighting and a target-set reference if replacing the environment.'], [
          step(['Tự quay clip gốc (plate) rõ và ổn định', 'Prepare a trackable plate'], 'Phone camera / CapCut', ['Quay 5–8 giây, không che mặt bằng tay và không lia nhanh. Cắt đoạn dư theo giới hạn upload thực tế; khi có nhiều clip, kiểm tổng thời lượng tham chiếu mà tool cho phép. Lưu bản gốc và một frame làm mốc bố cục.', 'Record five to eight seconds without face occlusion or fast pans. Trim to actual upload limits; with multiple clips, check the tool’s combined reference-duration limit. Preserve the original and a composition frame.'], 'refs/L4-live-plate.mp4 + plate-start.png'),
          step(['Chọn một phạm vi chỉnh', 'Choose one edit scope'], 'Video editing / VFX', ['Bài A chỉ thêm ánh đèn, bài B đổi phòng thành kho. Đừng làm cả hai ở lần đầu. Tải clip gốc và ảnh căn phòng vào hai ô riêng. Câu lệnh dưới dùng cho B; bài A dùng câu lệnh thêm ánh đèn ở phần học chính.', 'Exercise A adds lantern light; B changes the room into a storeroom. Do not combine both on the first take. Attach the plate and environment separately. The prompt below covers B; use the core lesson’s glow prompt for A.'], 'clips/L4-set-replacement.mp4', 'Use [PLATE] as the source performance and camera timing. Replace only the room behind the performer with the original storeroom in [SET]. Preserve the performer identity, clothing, gestures, duration and framing. Match the new background light direction and contact shadows to the plate. Keep all foreground objects unchanged. No new dialogue, people, camera moves or cuts.'),
          step(['Kiểm vùng không được đổi', 'Inspect protected regions'], 'Video player', ["Đối chiếu frame đầu, giữa và cuối, rồi xem toàn bộ clip. Kiểm tra tóc, bàn tay, viền vai, cửa, bóng đổ và âm thanh có thay đổi ngoài ý muốn không. Nếu tạo riêng một shot bổ sung, ghi rõ rằng diễn xuất trong shot đó được AI tạo mới. Nếu chưa có công cụ thêm hiệu ứng, ghép clip gốc và ảnh phòng trong phần mềm dựng để thử ý tưởng trước.", 'Compare start/middle/end and the full clip for hair, hands, shoulder edges, doors, shadows and sound drift. Separately generated inserts do not preserve the original performance. Without VFX access, combine the plate and set stills into an animatic to plan the scene.'], 'L4-VFX-QC.txt'),
        ], ['Nêu được phần cần thay, phần cần giữ và kiểm cả hai.', 'Allowed changes and preserved regions are specified and reviewed.'], ['Nếu cả người bị vẽ lại, giảm yêu cầu, dùng ảnh mẫu rõ hơn hoặc giữ clip gốc và thêm lớp hiệu ứng (overlay) trong phần mềm dựng.', 'If the performer is redrawn, narrow the edit, improve references or preserve the plate and add only an overlay in post.']),
      lab('performance-transfer', ['Video reference và Motion control: hai cách khác nhau', 'Video reference versus Motion control'],
        ["So sánh cách dùng video làm gợi ý diễn xuất với cách dùng video để điều khiển chuyển động cụ thể.", 'Compare performance guidance with more tightly driven movement.'],
        ["Một clip diễn tự quay và ảnh nhân vật có tư thế khớp với đầu clip. Nếu có hai diễn viên, tách clip từng người.", 'A self-recorded performance and character image matching the initial pose. Split separate actors into separate driving clips.'], [
          step(['Chuẩn bị hai bộ ảnh/clip đầu vào', 'Prepare two input sets'], 'CapCut / Image editing', ['Bộ A: ảnh mặt chính diện/góc nghiêng, ảnh phòng, ảnh mở đầu và clip diễn mẫu. Bộ B: clip quay liên tục một người, cùng ảnh mở đầu có tư thế, hướng mặt và cách lấy khung giống clip. Khi làm ảnh B, lấy hình đầu của clip làm mẫu.', 'Set A: identity views, set, start frame and a performance guide. Set B: one continuous single-person driving clip and a start image matching scale, pose and face direction. Use the driving clip’s first frame as composition guidance for B.'], 'L4-transfer-input-map.txt', 'Use the supplied driving-video first frame only for pose and composition. Replace the performer with the fictional repairer from the identity reference, preserving the same head angle, shoulder position and framing. Keep the indigo jacket and beige apron. One still image, no new gestures or camera angle.'),
          step(['Chạy hai chế độ nếu có', 'Run both modes if available'], 'Video reference / Motion control', ['Ở A dùng prompt diễn xuất của bài chính và gắn clip làm hướng dẫn. Ở B dùng ô Motion reference/Driving video, ảnh nhân vật vào ô image. Tên ô tùy công cụ; xem giới hạn thời lượng và kiểu chuyển động thực sự hỗ trợ. Không gắn nhầm video vào ô ảnh.', 'For A, use the core performance prompt with the guide clip. For B, place the driving clip in Motion reference/Driving video and the character in the image input. Labels vary; inspect supported duration and motion type. Do not put a video in an image field.'], 'clips/L4-transfer-A-B/'),
          step(['So nhịp, cảm xúc, mặt và phát âm', 'Compare timing, emotion, face and speech'], 'Video player / CapCut', ["Cách A có thể cho diễn xuất tự nhiên nhưng khác nhịp clip mẫu. Cách B có thể bám sát cử động tay và miệng hơn, nhưng làm mất một số chi tiết hình ảnh. Hãy kiểm tra kết quả thực tế của cả hai cách. So từng hành động: quay đầu, dừng, mỉm cười. Có thể ghép đoạn tốt từ các lần tạo, nhưng kiểm miệng vẫn khớp tiếng nói.", 'A may reinterpret acting but drift in timing; B may follow gestures more closely while losing detail. These are possibilities to test, not fixed rankings. Compare turn, pause and smile beats. Combine compatible sections if useful, checking lip/audio alignment.'], 'L4-transfer-scorecard.txt'),
        ], ["Biết cần chuẩn bị đầu vào nào cho từng chế độ và giải thích được lý do chọn một đoạn kết quả.", 'Both input schemes are understood and selection is based on specific segments.'], ["Nếu tay đi khỏi khung hoặc cơ thể méo, quay lại clip chuyển động ít hơn và khớp tư thế ở đầu clip; không tăng độ dài để chữa lỗi.", 'If hands leave frame or the body distorts, use a simpler driving clip with matching start pose; extending duration will not repair it.']),
    ],
    delivery: [
      lab('creative-brief', ['Mục tiêu, logline và moodboard', 'Objective, logline and moodboard'],
        ['Chọn mục đích trước khi tạo tài sản để mỗi quyết định hình ảnh có lý do.', 'Choose a purpose before generating assets so visual decisions have a reason.'],
        ['Ý tưởng “Ngọn đèn cuối cùng”; đầu ra 20–30 giây hoặc thời lượng bạn tự chọn.', 'The Last Lantern idea and a target of twenty to thirty seconds or a duration you choose.'], [
          step(['Viết brief một trang', 'Write a one-page brief'], 'Notes / Canvas', ["Ghi người xem, cảm xúc muốn để lại, nền tảng đăng video, tỷ lệ, thời lượng, giới hạn công cụ và credit. Ví dụ: phim ngắn tạo cảm giác hy vọng, không thoại, một phòng và một người. Mục tiêu dự thi/quảng cáo cần yêu cầu thật; không tự thêm giải thưởng hoặc khách hàng.", 'Record audience, final feeling, viewing context, ratio, duration, tool and credit limits. Example: a hopeful short, no dialogue, one room and one person. Competition or commercial requirements must be real; do not invent prizes or clients.'], 'L5-creative-brief.txt'),
          step(["Viết logline có tình huống và chuyển biến rõ ràng", 'Write a logline with a change'], 'Chat assistant', ['Dùng prompt rồi tự chọn một câu có nhân vật, vấn đề và chuyển biến nhìn thấy. “Một căn phòng đẹp” là bối cảnh, chưa phải câu chuyện. Bỏ ý tưởng cần nhiều nhân vật hoặc bối cảnh hơn ngân sách.', 'Use the prompt and choose one sentence with a protagonist, problem and visible change. “A beautiful room” is a setting, not a story. Remove ideas requiring more characters or locations than the budget allows.'], 'L5-logline.txt', 'Develop three original one-sentence loglines for a twenty-to-thirty-second silent film about a lantern repairer. Each must include a visible problem, one decisive action and a clear change. One adult character, one room and one lantern only. Avoid backstory, abstract themes that cannot be shown and additional locations. Explain what the audience should feel at the end.'),
          step(["Tạo moodboard và ghi rõ vai trò từng ảnh", 'Annotate the moodboard by purpose'], 'Canvas / Image board', ['Chọn 4–6 ảnh có quyền dùng: màu, hướng sáng, chất liệu, bố cục. Dưới mỗi ảnh ghi học điều gì; không trộn phong cách mâu thuẫn. Moodboard giúp thống nhất màu và phong cách. Muốn giữ cùng khuôn mặt, vẫn cần ảnh nhân vật riêng.', 'Choose four to six usable references for palette, light, materials and framing. Label what each contributes and avoid conflicting styles. A moodboard guides visual direction; it is not an identity reference.'], 'L5-moodboard + notes'),
        ], ['Mỗi ảnh moodboard liên hệ được với brief.', 'Every moodboard image supports the brief.'], ['Nếu moodboard chỉ là ảnh đẹp không liên quan, bỏ ảnh không giải thích được vai trò.', 'Remove attractive images whose contribution cannot be explained.']),
      lab('treatment-storyboard', ['Treatment → shot list → storyboard → frame', 'Treatment → shot list → storyboard → frame'],
        ["Chuyển phần mô tả câu chuyện thành từng shot cụ thể để tạo ảnh, video và dựng phim.", 'Translate prose into shots that can be generated, reviewed and edited.'],
        ['Brief, logline và danh sách tài sản đã chọn.', 'The brief, logline and chosen assets.'], [
          step(['Kể chuyện ngắn theo thứ tự hành động (treatment)', 'Write a treatment in visible actions'], 'Notes', ["Bốn beat (mốc hành động) mẫu: phòng tối; người kiểm tra đèn; ánh đèn trở lại; người đặt đèn cạnh cửa sổ. Viết mỗi beat một câu, diễn tả suy nghĩ và cảm xúc qua hành động nhìn thấy được. Thêm một chi tiết biểu hiện cảm xúc như vai thả lỏng.", 'Four sample beats: dark room, inspection, light returns, lantern by the window. Write one visible sentence per beat rather than unfilmable thoughts. Express feeling through a detail such as relaxing shoulders.'], 'L5-treatment.txt'),
          step(['Liệt kê từng đoạn quay (shot list), ghi hình đầu và hình cuối', 'Create a shot list with entry/exit states'], 'Chat assistant', ['Dán treatment vào prompt. Kiểm tổng thời lượng, thứ tự bật đèn và vị trí người. Nếu clip nguồn chỉ cho 5 giây, chia hành động dài thành shot riêng; không đòi giữ nguyên nhiều thao tác trong một clip.', 'Paste the treatment into the prompt. Verify duration totals, when the light turns on and character position. If clips are limited to five seconds, split long actions instead of overloading one generation.'], 'L5-shot-list-detailed.txt', 'Convert this treatment into four separately generated shots: [paste treatment]. Return shot ID, target duration, framing, camera move, one action, entry state, exit state, required reference files, sound cue and likely failure risk. Keep total duration between twenty and thirty seconds, but flag any shot exceeding my tool limit of [seconds]. Preserve the lantern state and room geography across cuts. Do not invent finished files.'),
          step(['Vẽ nháp trước khi tạo frame đẹp', 'Sketch before polishing frames'], 'Paper / Canvas / CapCut', ["Vẽ từng shot bằng hình khối, đánh dấu hướng nhìn và hướng chuyển động. Đưa ảnh nháp vào timeline với thời lượng dự kiến. Nếu câu chuyện chưa rõ khi xem animatic, sửa thứ tự hoặc thêm cảnh cận chi tiết, rồi mới tạo ảnh mở đầu hoàn chỉnh.", 'Sketch shapes, eyelines and movement arrows. Time the panels on an editing timeline. If the animatic does not communicate the story, revise order or add an insert before generating polished start frames.'], 'L5-storyboard-v02 + animatic.mp4'),
        ], ['Mỗi đoạn có ghi bắt đầu và kết thúc ra sao; đã cộng lại tổng thời lượng.', 'Each shot has entry/exit states and the total duration is checked.'], ['Nếu ảnh storyboard có nhiều ô, xuất riêng từng ô để dùng làm frame; không upload cả trang làm start frame.', 'Export storyboard panels individually; do not upload the whole page as a start frame.']),
      lab('canvas-lineage', ['Canvas: xếp ảnh/clip và ghi cách đã tạo chúng', 'Canvas: asset connections and generation lineage'],
        ["Từ mỗi clip đã chọn, tìm lại được prompt và ảnh đầu vào đã dùng để tạo clip đó.", 'Trace a selected clip back to its prompt and input assets.'],
        ['Brief, ảnh tham chiếu, storyboard, frames và clip đã có.', 'Existing brief, references, storyboard, frames and clips.'], [
          step(["Sắp xếp bảng dự án theo từng bước", 'Arrange the board by production stage'], 'TopView · Canvas / Project folders', ["Tạo nhóm brief → moodboard → refs → storyboard → frames → takes → edit → export. Chỉ nối các ảnh và clip thực sự được dùng làm đầu vào của bước tiếp theo. Nếu không có Canvas, dùng bảng văn bản với cùng các cột; không cần mua gói mới để tổ chức dự án.", 'Group brief → moodboard → refs → storyboard → frames → takes → edit → export. Connect assets actually used as inputs. Without Canvas, use a text table with the same columns; organization does not require another subscription.'], 'L5-board-layout.txt'),
          step(['Kiểm câu lệnh và ảnh mẫu đã dùng cho một file', 'Inspect an asset’s prompt and references'], 'Canvas · Asset details', ['Mở phần chi tiết file nếu có. Ghi tên model, câu lệnh, ảnh mẫu, thiết lập và ngày tạo. Khi chọn “from canvas” (lấy ảnh từ bảng), kiểm đã chọn đúng ảnh. Nếu công cụ không lưu các thông tin này, tự ghi ngay sau mỗi lần tạo.', 'Open asset details/info if available and record model, prompt, references, settings and date. When choosing from Canvas, verify the intended image is attached. If metadata is not retained, record it immediately after generation.'], 'L5-asset-register.txt'),
          step(['Phân biệt “đang cân nhắc” (candidate) và “đã chọn” (selected)', 'Distinguish candidates from selected assets'], 'Notes', ['Ví dụ: S02-take01 là lần tạo 1 của đoạn quay 2. Sau khi xem, ghi “đã chọn” và thời điểm bắt đầu/kết thúc đoạn muốn dùng, ví dụ 00:01–00:04. Lưu cả câu lệnh và ảnh đầu vào. Chưa xem xong thì đừng đặt tên “final” (bản cuối).', 'Name S02-take01 and S02-take02; mark selected with in/out points only after review. Do not call a pending clip final. Retain prompt versions and input relationships so a changed lantern reference identifies shots needing review.'], 'L5-selection-register.txt'),
        ], ['Từ clip đã chọn, tìm lại được đúng ảnh đầu vào và câu lệnh đã dùng.', 'A selected clip can be traced to its exact inputs and prompt.'], ['Nếu không biết take nào dùng frame nào, dừng và đối chiếu lịch sử công cụ; ghi “chưa biết” thay vì đoán.', 'If input lineage is unclear, inspect tool history and mark unknown rather than guessing.']),
      lab('assembly-sound', ["Hoàn thiện phim: nhịp dựng, lời thoại, âm nhạc và kiểm tra file", 'Final assembly: pacing, voice, music and file review'],
        ["Chọn các đoạn dùng được, thêm âm thanh phù hợp với cảnh và kiểm tra file video đã xuất.", 'Select usable segments, build intentional sound and inspect the actual export.'],
        ['Take được chọn, in/out timecode, âm thanh có quyền dùng và dự án CapCut.', 'Selected takes, in/out timecodes, usable audio and a CapCut project.'], [
          step(["Hoàn thiện phần hình trước khi làm âm thanh", 'Establish picture lock first'], 'CapCut · Timeline', ["Xếp các shot theo diễn biến câu chuyện. Cắt bỏ phần lỗi ở đầu hoặc cuối clip, frame đen và đoạn có bàn tay biến dạng. Xem tắt tiếng; chỉ dùng transition nếu có lý do. Nếu cần reaction shot để dễ hiểu, bổ sung trước khi làm nhạc để tránh phải phối lại.", 'Arrange story order, trim faulty starts/ends and remove black frames or deformed hands. Watch muted and use transitions deliberately. Add needed reactions before music to avoid unnecessary remixing.'], 'L5-picture-lock project'),
          step(['Tạo ba lớp âm thanh', 'Build three audio layers'], 'CapCut · Audio', ["Lớp thứ nhất là âm thanh nền của căn phòng, chạy liền qua các điểm cắt. Lớp thứ hai là tiếng công tắc hoặc tiếng đặt đèn, khớp với hành động. Lớp thứ ba là nhạc nhẹ, nếu phù hợp. Giọng phải rõ hơn nhạc. Tắt audio AI có tiếng lạ. Nghe tai nghe và loa điện thoại, để kiểm tra bằng tai thay vì chỉ nhìn biểu đồ sóng âm.", 'Layer one: room tone across cuts; two: switch/prop cues at the action; three: optional restrained music. Keep speech intelligible above music and mute unwanted generated audio. Listen through headphones and phone speakers, not just waveforms.'], 'L5-sound-map.txt'),
          step(['Mở file MP4 đã xuất để kiểm tra', 'Review the export independently'], 'Export / Video player', ['Xuất MP4, chọn độ phân giải phù hợp nguồn và cùng fps (số hình trong mỗi giây). Mở ngoài trình dựng, xem/nghe từ đầu đến cuối. Kiểm chữ, viền, màu đèn, âm lượng, tiếng Việt và điểm cắt. Nếu sửa, lưu thành bản v02 rồi xem lại file mới; bản xem trong phần mềm có thể khác file đã xuất.', 'Export MP4 at source-appropriate resolution and consistent fps. Watch/listen outside the editor end to end. Check text, borders, lantern color, volume, speech and cuts. After fixes, version and review the new file; a correct timeline does not prove a correct export.'], 'exports/Den-cuoi-cung-v02.mp4 + L5-export-QC.txt'),
        ], ['File đã mở trên hai thiết bị và các lỗi còn lại được ghi rõ.', 'The file was reviewed on two devices and remaining limitations are documented.'], ['Nếu âm thanh méo, giảm gain (mức âm lượng) ở lớp gây lỗi và xuất lại; giảm âm lượng trình phát không sửa clipping (âm thanh bị vỡ do quá lớn) đã có trong file.', 'If sound clips, reduce the offending layer’s gain and re-export; turning down playback does not repair clipping in the file.']),
      lab('thumbnail-delivery', ['Thumbnail, tiêu đề và bộ bàn giao', 'Thumbnail, title and delivery package'],
        ["Chuẩn bị ảnh bìa và phần giới thiệu phim. Lưu đủ tư liệu để có thể chỉnh sửa hoặc làm phiên bản tiếp theo.", 'Prepare how viewers encounter the film and retain assets for future revisions.'],
        ['MP4 đã duyệt và một frame có cảm xúc/đạo cụ rõ.', 'A reviewed MP4 and a frame with a clear emotional or prop focal point.'], [
          step(['Chọn ảnh bìa đúng nội dung phim', 'Choose a truthful thumbnail'], 'Image editor', ['Chọn mặt phản ứng cạnh đèn sáng hoặc hình đèn rõ, không chọn cảnh không có trong phim. Chừa vùng đặt chữ, dùng ít chữ và tương phản tốt. Thu nhỏ ảnh để kiểm tra khuôn mặt và chiếc đèn có còn dễ nhận ra không.', 'Choose the reaction beside the lit lantern or a clear prop frame rather than a scene absent from the film. Reserve text space, keep wording brief and use contrast. Check at small size for recognizable face and lantern.'], 'exports/thumbnail.png', 'Create a thumbnail layout from my approved film frame. Preserve the repairer and lantern exactly; simplify only nonessential background clutter. Keep the face and glowing lantern as the two focal points and leave clean space for a short title that I will add in an editor. No generated text, new story events or misleading objects.'),
          step(['Viết phần giới thiệu ngắn', 'Write a short introduction'], 'Notes / Chat assistant', ['Ghi tên phim, một câu gợi tình huống, công cụ đã dùng và nguồn nhạc. Nói rõ đây là phim thực hành có AI hỗ trợ. Nếu đăng lên nền tảng, tự chọn chế độ công khai và kiểm yêu cầu công bố AI hiện tại; bài này không tự đăng.', 'Include title, one premise sentence, tools used and music credit. Describe it as an AI-assisted practice film. If publishing, choose visibility and inspect the platform’s current disclosure requirements yourself; this exercise does not publish automatically.'], 'L5-title-description.txt'),
          step(['Kiểm bộ bàn giao', 'Check the delivery package'], 'Project folder', ['Bộ bàn giao gồm MP4, ảnh bìa, file dự án dựng, kế hoạch, câu lệnh, ảnh mẫu, ghi chú các lần tạo, nguồn âm thanh và kết quả kiểm tra cuối. Ghi điều tốt nhất, lỗi lớn nhất và một kỹ thuật sẽ thử lần sau. Giữ ảnh, clip và âm thanh đã chọn trong cùng cấu trúc thư mục, tránh đổi vị trí file khiến dự án không tìm thấy tư liệu khi mở lại.', 'Retain MP4, thumbnail, editing project, brief, prompts, references, take log, audio sources and final checks. Record the strongest result, largest issue and one next technique. Keep selected assets with stable relative paths so the edit reopens.'], 'L5-delivery-manifest.txt'),
        ], ["Ảnh bìa đúng nội dung phim, dự án mở lại được và file video cuối được đặt tên rõ ràng.", 'Thumbnail matches the story, the project reopens and the final file is unambiguous.'], ['Nếu phần mềm báo thiếu ảnh/clip, đưa file về đúng thư mục rồi chọn lại đường dẫn (relink). File dự án dựng cần đi kèm ảnh, clip và âm thanh đã dùng.', 'If media is missing, collect and relink it; an editing project without its media is not a complete handoff.']),
    ],
  };
}
